solution.solution.cpp:
class Counter
{
public:
    void increment() { ++m_count; }
    void reset() { m_count = 0; }
    int count() const { return m_count; }

private:
    int m_count{ 0 };
};

unitTests:
TEST("starts at zero") { Counter c{}; CHECK_EQ(c.count(), 0); }
TEST("increment") { Counter c{}; c.increment(); c.increment(); c.increment(); CHECK_EQ(c.count(), 3); }
TEST("reset") { Counter c{}; c.increment(); c.reset(); CHECK_EQ(c.count(), 0); }
TEST("each object has its own count") { Counter a{}, b{}; a.increment(); CHECK_EQ(a.count(), 1); CHECK_EQ(b.count(), 0); }
TEST("count works on a const object") { const Counter c{}; CHECK_EQ(c.count(), 0); }

